const body = $json.body || $json;

const content = body.content || body.memory || body.text || body.message || "";
if (!content || !content.trim()) {
  return [{ json: { ok: false, error: "content is required" } }];
}

let tags = [];
if (Array.isArray(body.tags)) {
  tags = body.tags;
} else if (typeof body.tags === "string") {
  tags = body.tags.split(",").map(t => t.trim()).filter(Boolean);
}

const variables = {
  kind: body.kind || "note",
  title: body.title || null,
  content,
  tags,
  importance: Number(body.importance || 3),
  source: body.source || "openwebui"
};

const query = `
mutation SaveMemory(
  $kind: String!,
  $title: String,
  $content: String!,
  $tags: [String],
  $importance: Int,
  $source: String
) {
  createAgenticsMemory(input: {
    agenticsMemory: {
      kind: $kind,
      title: $title,
      content: $content,
      tags: $tags,
      importance: $importance,
      source: $source
    }
  }) {
    agenticsMemory {
      id
      kind
      title
      content
      tags
      importance
      source
      createdAt
      updatedAt
    }
  }
}
`;

const res = await fetch("http://postgraphile:5000/graphql", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ query, variables })
});

const data = await res.json();

if (data.errors) {
  return [{ json: { ok: false, errors: data.errors } }];
}

return [{
  json: {
    ok: true,
    action: "memory_saved",
    memory: data.data.createAgenticsMemory.agenticsMemory
  }
}];
